import type { CalculatorGoldenTest } from "./types";

/** Literal expectations, independently derived from the historical Math.round
 * contract and integer fraction reduction; never generated by the engine.
 * References: ECMA-262 Math.round / Number.EPSILON and the existing launch spec.
 * Large-value rows preserve compatibility, not an exact-decimal guarantee.
 */
export const decimalFractionVectors = [
  { label: "Precision 0: round(0.125) = 0", input: { decimal: 0.125, precision: 0 }, expected: { result: 0 }, fraction: "0/1" },
  { label: "Precision 1: round(1.25)/10 = 1/10", input: { decimal: 0.125, precision: 1 }, expected: { result: 0.1 }, fraction: "1/10" },
  { label: "Precision 2: positive half rounds to 13/100", input: { decimal: 0.125, precision: 2 }, expected: { result: 0.13 }, fraction: "13/100" },
  { label: "Precision 3: 125/1000 = 1/8", input: { decimal: 0.125, precision: 3 }, expected: { result: 0.125 }, fraction: "1/8" },
  { label: "Precision 4: 1250/10000 = 1/8", input: { decimal: 0.125, precision: 4 }, expected: { result: 0.125 }, fraction: "1/8" },
  { label: "Precision 5: 12500/100000 = 1/8", input: { decimal: 0.125, precision: 5 }, expected: { result: 0.125 }, fraction: "1/8" },
  { label: "Precision 6: 125000/1000000 = 1/8", input: { decimal: 0.125, precision: 6 }, expected: { result: 0.125 }, fraction: "1/8" },
  { label: "Precision 7: 1250000/10000000 = 1/8", input: { decimal: 0.125, precision: 7 }, expected: { result: 0.125 }, fraction: "1/8" },
  { label: "Precision 8: 12500000/100000000 = 1/8", input: { decimal: 0.125, precision: 8 }, expected: { result: 0.125 }, fraction: "1/8" },
  { label: "Precision 9: 125000000/1000000000 = 1/8", input: { decimal: 0.125, precision: 9 }, expected: { result: 0.125 }, fraction: "1/8" },
  { label: "Precision 10: 1250000000/10000000000 = 1/8", input: { decimal: 0.125, precision: 10 }, expected: { result: 0.125 }, fraction: "1/8" },
  { label: "Precision 11: 12500000000/100000000000 = 1/8", input: { decimal: 0.125, precision: 11 }, expected: { result: 0.125 }, fraction: "1/8" },
  { label: "Precision 12: 125000000000/1000000000000 = 1/8", input: { decimal: 0.125, precision: 12 }, expected: { result: 0.125 }, fraction: "1/8" },
  { label: "Negative half rounds toward positive infinity: -12/100 = -3/25", input: { decimal: -0.125, precision: 2 }, expected: { result: -0.12 }, fraction: "-3/25" },
  { label: "75/100 reduces to 3/4", input: { decimal: 0.75, precision: 2 }, expected: { result: 0.75 }, fraction: "3/4" },
  { label: "-125/100 reduces to -5/4", input: { decimal: -1.25, precision: 2 }, expected: { result: -1.25 }, fraction: "-5/4" },
  { label: "Existing EPSILON adjustment: 1.005 rounds to 101/100", input: { decimal: 1.005, precision: 2 }, expected: { result: 1.01 }, fraction: "101/100" },
  { label: "Negative zero from the existing negative half tie", input: { decimal: -0.5, precision: 0 }, expected: { result: -0 }, fraction: "0/1" },
  { label: "Positive half tie: 0.5 rounds to 1", input: { decimal: 0.5, precision: 0 }, expected: { result: 1 }, fraction: "1/1" },
  { label: "Zero at maximum precision", input: { decimal: 0, precision: 12 }, expected: { result: 0 }, fraction: "0/1" },
  { label: "Maximum safe integer numerator at precision zero", input: { decimal: 9007199254740991, precision: 0 }, expected: { result: 9007199254740991 }, fraction: "9007199254740991/1" },
  { label: "Safe scaled integer: 9000000000000000 / 1000000000000", input: { decimal: 9000, precision: 12 }, expected: { result: 9000 }, fraction: "9000/1" },
  { label: "Accepted exact but unsafe-range scaled integer: 9008000000000000 / 1000000000000", input: { decimal: 9008, precision: 12 }, expected: { result: 9008 }, fraction: "9008/1" },
  { label: "Existing exponential display for a large accepted integer", input: { decimal: 1e21, precision: 0 }, expected: { result: 1e21 }, fraction: "1e+21/1" }
] as const;

export const decimalFractionGoldenTests: readonly CalculatorGoldenTest<Record<string, number>, { result: number }>[] =
  decimalFractionVectors.map(({ label, input, expected }) => ({ label, input, expected }));
